SELECT 
FROM building_shop_owner sl
LEFT JOIN building_shop bs ON sl.shop_id = bs.shop_id
LEFT JOIN shop_location sls ON bs.location_id = sls.location_id


        AND sl.shop_owner_id = #{shopOwnerId}


        AND sl.shop_id = #{shopId}


        AND sl.owner_id = #{ownerId}


        AND sl.owner_name LIKE '%${ownerName}%'


        AND sl.link = #{link}


        AND sl.state = #{state}


        AND sl.community_id = #{communityId}


        AND bs.shop_num LIKE '%${shopNum}%'


        AND bs.location_id = #{locationId}

    AND sl.status_cd = '0'


    ORDER BY ${orderByClause}


    ${limitClause}

SELECT COUNT(1) count FROM building_shop_owner sl
LEFT JOIN building_shop bs ON sl.shop_id = bs.shop_id
LEFT JOIN shop_location sls ON bs.location_id = sls.location_id


        AND sl.shop_owner_id = #{shopOwnerId}


        AND sl.shop_id = #{shopId}


        AND sl.owner_id = #{ownerId}


        AND sl.owner_name LIKE '%${ownerName}%'


        AND sl.link = #{link}


        AND sl.state = #{state}


        AND sl.community_id = #{communityId}


        AND bs.shop_num LIKE '%${shopNum}%'


        AND bs.location_id = #{locationId}

    AND sl.status_cd = '0'
